import { cn } from "@/lib/utils"

/**
 * Total Wireless Toggle Group / Segmented Control Component
 *
 * Used for switching between "Phone" / "Bring your phone" / "Tablet"
 * options at the top of the plan listing page.
 *
 * Based on the segmented control in the desktop and mobile designs.
 *
 * Usage:
 * <SegmentedControl
 *   value="phone"
 *   onChange={setValue}
 *   options={[
 *     { value: "phone", label: "Phone" },
 *     { value: "byop", label: "Bring your phone" },
 *     { value: "tablet", label: "Tablet" },
 *   ]}
 * />
 */

interface SegmentOption {
  value: string
  label: string
  icon?: React.ReactNode
}

interface SegmentedControlProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  value: string
  onChange?: (value: string) => void
  options: SegmentOption[]
}

function SegmentedControl({
  className,
  value,
  onChange,
  options,
  ...props
}: SegmentedControlProps) {
  return (
    <div
      data-slot="segmented-control"
      className={cn(
        "inline-flex items-center rounded-full bg-tw-gray-100 p-1 gap-1",
        className
      )}
      role="tablist"
      {...props}
    >
      {options.map((option) => (
        <button
          key={option.value}
          type="button"
          role="tab"
          aria-selected={value === option.value}
          onClick={() => onChange?.(option.value)}
          className={cn(
            "inline-flex items-center gap-1.5 rounded-full px-4 py-2 text-sm font-medium transition-all cursor-pointer",
            value === option.value
              ? "bg-white text-tw-gray-900 shadow-sm"
              : "text-tw-gray-500 hover:text-tw-gray-700"
          )}
        >
          {option.icon}
          {option.label}
        </button>
      ))}
    </div>
  )
}

export { SegmentedControl }
export type { SegmentedControlProps, SegmentOption }
